}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": [{"werte": {"d": "25"}, "fehlbilder": [{"key": "qf_binom_vorzeichen", "werte": {"d": "-25"}}, {"key": "qf_binom_b_statt_halb", "werte": {"d": "50"}}, {"key": "qf_binom_c_statt_wurzel", "werte": {"d": "625"}}]}], "acceptance": null, "parts": null, "figur": null, "optionen": null, "solution": "x² + 50x + 625\n= x² + 2 · 25 · x + 25²\n= (x + 25)²", "hints": [{"level": 1, "text": "Welche binomische Formel hat drei Glieder wie x² + 50x + 625?", "status": "entwurf"}, {"level": 2, "text": "Die Zahl am Ende ist ein Quadrat. Von welcher Zahl?", "status": "entwurf"}, {"level": 3, "text": "Vergleiche mit x² + 2 · d · x + d². Was ist d?", "status": "entwurf"}]}, {"suffix": "uebung-s3-c7ae1507ec", "input_type": "FELDMASKE", "frage": "Schreib x² + 36x + 324 als Quadrat.", "payload": {"format": "feldmaske", "schablone": [{"text": "(x "}, {"feld": "vd", "typ": "vorzeichen"}, {"feld": "d", "typ": "zahl"}, {"text": ")²"}]}, "params": {"d": 18}, "stufe": 3, "rolle": "uebung", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": [{"werte": {"d": "18"}, "fehlbilder": [{"key": "qf_binom_vorzeichen", "werte": {"d": "-18"}}, {"key": "qf_binom_b_statt_halb", "werte": {"d": "36"}}, {"key": "qf_binom_c_statt_wurzel", "werte": {"d": "324"}}]}], "acceptance": null, "parts": null, "figur": null, "optionen": null, "solution": "x² + 36x + 324\n= x² + 2 · 18 · x + 18²\n= (x + 18)²", "hints": [{"level": 1, "text": "Welche binomische Formel hat drei Glieder wie x² + 36x + 324?", "status": "entwurf"}, {"level": 2, "text": "Die Zahl am Ende ist ein Quadrat. Von welcher Zahl?", "status": "entwurf"}, {"level": 3, "text": "Vergleiche mit x² + 2 · d · x + d². Was ist d?", "status": "entwurf"}]}]'::jsonb)
             as v(suffix text, input_type text, frage text, payload jsonb, params jsonb, stufe int, rolle text,
                  pm jsonb, afb text, correct jsonb, acceptance jsonb, parts jsonb, figur jsonb, optionen jsonb,
                  solution text, hints jsonb)),
     neu as (
  insert into public.tasks (content_type, input_type, status, is_active, title, question, question_payload, parts, skill_key,
                            difficulty, afb, class_level, est_duration_sec, source, source_ref, einsatz, bauform_id,
                            bauform_version, params, stufe, rolle, kernidee_key, pruefmaschine)
  select 'exercise', v.input_type, 'draft', true, 'BIN-2' || ' · ' || v.rolle || ' · S' || v.stufe, v.frage,
         v.payload, coalesce(v.parts, '[]'::jsonb), 'term_binom_quadrat', v.stufe, v.afb, 9, 60, 'bauform',
         'BIN-2' || '-v' || b.version || '-' || v.suffix, '{session}', b.id, b.version, v.params, v.stufe,
         v.rolle, null, v.pm
    from b, v
  on conflict (source, source_ref) do nothing
  returning id, source_ref),
     loes as (
  insert into public.task_solutions (task_id, correct_answers, acceptance, solution, hints)
  select neu.id, v.correct, v.acceptance, v.solution, v.hints
    from neu join b on true join v on neu.source_ref = 'BIN-2' || '-v' || b.version || '-' || v.suffix
  returning task_id),
     fig as (
  -- Eine Figur je Aufgabe (task_figures) bzw. je Option einer Graph-Auswahl (task_figur_optionen); hochgeladen
  -- werden sie von scripts/figures/upload_figures.py (Rasit).
  insert into public.task_figures (task_id, generator, params, alt_text)
  select neu.id, v.figur ->> 'generator', v.figur -> 'params', v.figur ->> 'alt'
    from neu join b on true join v on neu.source_ref = 'BIN-2' || '-v' || b.version || '-' || v.suffix
   where v.figur is not null
  returning task_id)
insert into public.task_figur_optionen (task_id, option_id, generator, params, alt_text)
select neu.id, o ->> 'option', o ->> 'generator', o -> 'params', o ->> 'alt'
  from neu join b on true join v on neu.source_ref = 'BIN-2' || '-v' || b.version || '-' || v.suffix,
       jsonb_array_elements(coalesce(v.optionen, '[]')) o;
do $$ begin perform set_config('edvance.hinweis_status', '', true); perform set_config('edvance.bauform_export', '', true); end $$;
